const fs = require('fs');
const request = require('request');

function processCustomerData(customerId, callback) {
  fs.readFile(`./customers/${customerId}.json`, (err, data) => {
    if (err) return callback(err);

    const customer = JSON.parse(data);
    request.post({
      url: 'https://api.example.com/validate',
      json: customer
    }, (error, response, body) => {
      if (error) return callback(error);

      if (response.statusCode !== 200) {
        return callback(new Error(`API error: ${response.statusCode}`));
      }

      customer.validated = true;
      fs.writeFile(`./customers/${customerId}.json`, 
        JSON.stringify(customer, null, 2), 
        (writeErr) => {
          if (writeErr) return callback(writeErr);
          callback(null, 'Customer processed successfully');
        }
      );
    });
  });
}

module.exports = { processCustomerData };

pub struct List<T> {
    head: Option<Box<Node<T>>>,
}

struct Node<T> {
    elem: T,
    next: Option<Box<Node<T>>>,
}

impl<T> List<T> {
    pub fn new() -> Self {
        List { head: None }
    }

    pub fn pop(&mut self) -> Option<T> {
        match self.head {
            None => None,
            Some(node) => {
                self.head = node.next;
                Some(node.elem)
            }
        }
    }
}

